const button = document.querySelector('#toggle-button');
const panel = document.querySelector('#panel');

if (!button || !panel) throw new Error('Elementi #toggle-button e #panel non trovati.');

button.addEventListener('click', () => {
  const expanded = button.getAttribute('aria-expanded') === 'true';
  button.setAttribute('aria-expanded', String(!expanded));
  panel.classList.toggle('is-visible', !expanded);
});

async function fetchJson(url, options = {}, retries = 2) {
  let lastError;

  for (let attempt = 0; attempt <= retries; attempt += 1) {
    try {
      const response = await fetch(url, {
        ...options,
        headers: { Accept: 'application/json', ...options.headers }
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      return await response.json();
    } catch (error) {
      lastError = error;
      if (attempt < retries) await new Promise((resolve) => setTimeout(resolve, 300 * 2 ** attempt));
    }
  }

  throw lastError;
}

const form = document.querySelector('#my-form');

if (!form) throw new Error('Form #my-form non trovato.');

form.addEventListener('submit', (event) => {
  event.preventDefault();
  form.querySelectorAll('[aria-invalid]').forEach((field) => field.removeAttribute('aria-invalid'));
  const data = new FormData(form);
  const email = String(data.get('email') || '').trim();
  const emailField = form.elements.email;

  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    emailField?.setAttribute('aria-invalid', 'true');
    emailField?.focus();
    return;
  }

  console.log('Form valido:', Object.fromEntries(data));
});

const STORAGE_KEY = 'app-settings';

export function loadSettings(fallback = {}) {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? { ...fallback, ...JSON.parse(raw) } : fallback;
  } catch (error) {
    console.warn('Impostazioni non leggibili:', error);
    return fallback;
  }
}

export function saveSettings(settings) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
    return true;
  } catch (error) {
    console.warn('Impostazioni non salvate:', error);
    return false;
  }
}

const input = document.querySelector('#search');
const items = [...document.querySelectorAll('[data-search-item]')];

input?.addEventListener('input', () => {
  const query = input.value.trim().toLocaleLowerCase();
  items.forEach((item) => {
    const matches = item.textContent.toLocaleLowerCase().includes(query);
    item.hidden = !matches;
  });
});

async function withLoading(button, task) {
  const label = button?.textContent;
  if (button) { button.disabled = true; button.textContent = 'Caricamento...'; }

  try {
    return await task();
  } catch (error) {
    console.error('Operazione fallita:', error);
    throw error;
  } finally {
    if (button) { button.disabled = false; button.textContent = label; }
  }
}
